UPDATE voj_contests 
SET contest_name = #{contestName}, contest_notes = #{contestNotes}, contest_start_time = #{startTime}, contest_end_time = #{endTime}, contest_status = #{status}, contest_scoring = #{scoring}, contest_penalty = #{penalty}, contest_freeze = #{freeze}, contest_open_registration = #{openRegistration}
WHERE contest_id = #{contestId}

